arguments.command:
python -I -c 'import json,sys,statistics; rows=[json.loads(x)["data"] for x in open(sys.argv[1]) if x.strip()]; train=[(i+1,r) for i,r in enumerate(rows) if "critic/score/mean" in r];
for a,b in [(1,10),(11,50),(51,100),(101,150)]:
 q=[r for i,r in train if a<=i<=b]; print(f"steps {a}-{b}");
 for k in ["critic/score/mean","actor/grad_norm","actor/ppo_kl","actor/pg_clipfrac","actor/entropy","response_length/mean","response_length/clip_ratio","timing_s/step"]: print(k,"mean",statistics.mean(r[k] for r in q),"first",q[0][k],"last",q[-1][k],"min",min(r[k] for r in q),"max",max(r[k] for r in q))' /workspace/outputs/metrics.jsonl

