arguments.command:
python -I -c 'import json,sys,re,statistics,collections; 
for p in sys.argv[1:]:
 rows=[json.loads(x) for x in open(p) if x.strip()]; noanswer=[r for r in rows if not re.search(r"(?im)^\s*Answer:\s*",r["output"])]; noboxed=[r for r in rows if "\\boxed{" not in r["output"]]; print("\n",p); print("no Answer and no boxed",sum(not re.search(r"(?im)^\s*Answer:\s*",r["output"]) and "\\boxed{" not in r["output"] for r in rows)); print("unterminated-like suffixes");
 for r in noboxed[:5]: print(r["problem_id"],"score",r["score"],"len",len(r["output"]),"suffix",repr(r["output"][-300:]));
 print("score with/without Answer",{str(bool(a)): (len(q),statistics.mean(r["score"] for r in q)) for a in [True,False] for q in [[r for r in rows if bool(re.search(r"(?im)^\s*Answer:\s*",r["output"]))==a]]})' /workspace/outputs/rollouts/1.jsonl /workspace/outputs/rollouts/150.jsonl /workspace/outputs/frozen_eval/0.jsonl /workspace/outputs/frozen_eval/150.jsonl

