python -I -c 'import json,sys,collections,statistics; a=[json.loads(x) for x in open(sys.argv[1]) if x.strip()]; b=[json.loads(x) for x in open(sys.argv[2]) if x.strip()];
for label,rows in [("step0",a),("step150",b)]:
 print(label,"correct",sum(r["score"] for r in rows),"of",len(rows));
 for src in ["aime24","aime25"]:
  q=[r for r in rows if r["data_source"]==src]; print(src,"correct",sum(r["score"] for r in q),"of",len(q),"problems_with_any_correct",sum(any(r["score"] for r in q if r["problem_id"]==pid) for pid in set(r["problem_id"] for r in q)))
ga=collections.defaultdict(list); gb=collections.defaultdict(list)
for r in a: ga[r["problem_id"]].append(r["score"])
for r in b: gb[r["problem_id"]].append(r["score"])
print("paired problems: improved mean",sum(statistics.mean(gb[p])>statistics.mean(ga[p]) for p in ga),"worsened",sum(statistics.mean(gb[p])<statistics.mean(ga[p]) for p in ga),"unchanged",sum(statistics.mean(gb[p])==statistics.mean(ga[p]) for p in ga)); print("paired problems: gained any correct",sum(max(gb[p])>max(ga[p]) for p in ga),"lost any correct",sum(max(gb[p])<max(ga[p]) for p in ga))' /workspace/outputs/frozen_eval/0.jsonl /workspace/outputs/frozen_eval/150.jsonl

